import{_ as a,C as t,o as n,c as p,k as s,a as e,H as l,Q as c}from"./chunks/framework.5916b37e.js";const v=JSON.parse('{"title":"Upgrading to 4.0","description":"","frontmatter":{},"headers":[],"relativePath":"guide/upgrading-to-4.md","filePath":"guide/upgrading-to-4.md"}'),r={name:"guide/upgrading-to-4.md"},d={id:"upgrading-to-4-0",tabindex:"-1"},i=s("a",{class:"header-anchor",href:"#upgrading-to-4-0","aria-label":'Permalink to "Upgrading to 4.0 <Badge type="warning" text="breaking" />"'},"​",-1),h=c(`<p>4.0.0 is a packaging release. The copper3d API itself is unchanged — every class, method and type from 3.11.x still works the same way. What changed is <strong>how three.js reaches you</strong>, and that needs a change on your side.</p><h2 id="the-one-required-change" tabindex="-1">The one required change <a class="header-anchor" href="#the-one-required-change" aria-label="Permalink to &quot;The one required change&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#B392F0;">npm</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">install</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">copper3d</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">three@~0.186.0</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#6F42C1;">npm</span><span style="color:#24292E;"> </span><span style="color:#032F62;">install</span><span style="color:#24292E;"> </span><span style="color:#032F62;">copper3d</span><span style="color:#24292E;"> </span><span style="color:#032F62;">three@~0.186.0</span></span></code></pre></div><p><code>three</code> is now a <strong>peer dependency</strong>. Previously copper3d depended on three and bundled it; now you install it and copper3d shares your copy.</p><p>TypeScript users also want the types, which are an <em>optional</em> peer:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#B392F0;">npm</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">install</span><span style="color:#E1E4E8;"> </span><span style="color:#79B8FF;">-D</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">@types/three@~0.186.0</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#6F42C1;">npm</span><span style="color:#24292E;"> </span><span style="color:#032F62;">install</span><span style="color:#24292E;"> </span><span style="color:#005CC5;">-D</span><span style="color:#24292E;"> </span><span style="color:#032F62;">@types/three@~0.186.0</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Why peer, not bundled</p><p>Bundling three gave the page two copies. three itself warns about this — <em>&quot;Multiple instances of Three.js being imported&quot;</em> — and the consequence is worse than the warning: a <code>Mesh</code> your code builds is not an <code>instanceof</code> the <code>Mesh</code> copper3d checks against, because they come from different modules. Anything you pass across the boundary — a camera, a scene, a geometry — had to survive that.</p><p>With a peer dependency there is exactly one three on the page, and objects cross freely.</p></div><h2 id="what-else-changed" tabindex="-1">What else changed <a class="header-anchor" href="#what-else-changed" aria-label="Permalink to &quot;What else changed&quot;">​</a></h2><table><thead><tr><th></th><th>3.11.x</th><th>4.0.0</th></tr></thead><tbody><tr><td>three</td><td>bundled dependency, <code>^0.185.1</code></td><td><strong>peer</strong> dependency, <code>~0.186.0</code></td></tr><tr><td><code>@types/three</code></td><td>dependency</td><td>optional peer, <code>~0.186.0</code></td></tr><tr><td>ESM bundle</td><td><code>dist/bundle.esm.js</code></td><td><code>dist/bundle.esm.mjs</code></td></tr><tr><td><code>package.json</code> <code>module</code> field</td><td><code>&quot;moudle&quot;</code> <em>(typo — never resolved)</em></td><td><code>&quot;module&quot;</code>, plus a real <code>exports</code> map</td></tr><tr><td>three addon imports</td><td><code>three/examples/jsm/…</code></td><td><code>three/addons/…</code></td></tr></tbody></table><h3 id="the-exports-map" tabindex="-1">The <code>exports</code> map <a class="header-anchor" href="#the-exports-map" aria-label="Permalink to &quot;The \`exports\` map&quot;">​</a></h3><p><code>package.json</code> now declares one:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#E1E4E8;">{</span></span>
<span class="line"><span style="color:#E1E4E8;">  </span><span style="color:#79B8FF;">&quot;exports&quot;</span><span style="color:#E1E4E8;">: {</span></span>
<span class="line"><span style="color:#E1E4E8;">    </span><span style="color:#79B8FF;">&quot;.&quot;</span><span style="color:#E1E4E8;">: {</span></span>
<span class="line"><span style="color:#E1E4E8;">      </span><span style="color:#79B8FF;">&quot;types&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;./dist/types/index.d.ts&quot;</span><span style="color:#E1E4E8;">,</span></span>
<span class="line"><span style="color:#E1E4E8;">      </span><span style="color:#79B8FF;">&quot;import&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;./dist/bundle.esm.mjs&quot;</span><span style="color:#E1E4E8;">,</span></span>
<span class="line"><span style="color:#E1E4E8;">      </span><span style="color:#79B8FF;">&quot;require&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;./dist/bundle.umd.js&quot;</span></span>
<span class="line"><span style="color:#E1E4E8;">    },</span></span>
<span class="line"><span style="color:#E1E4E8;">    </span><span style="color:#79B8FF;">&quot;./dist/css/*&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;./dist/css/*&quot;</span><span style="color:#E1E4E8;">,</span></span>
<span class="line"><span style="color:#E1E4E8;">    </span><span style="color:#79B8FF;">&quot;./package.json&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;./package.json&quot;</span></span>
<span class="line"><span style="color:#E1E4E8;">  }</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292E;">{</span></span>
<span class="line"><span style="color:#24292E;">  </span><span style="color:#005CC5;">&quot;exports&quot;</span><span style="color:#24292E;">: {</span></span>
<span class="line"><span style="color:#24292E;">    </span><span style="color:#005CC5;">&quot;.&quot;</span><span style="color:#24292E;">: {</span></span>
<span class="line"><span style="color:#24292E;">      </span><span style="color:#005CC5;">&quot;types&quot;</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&quot;./dist/types/index.d.ts&quot;</span><span style="color:#24292E;">,</span></span>
<span class="line"><span style="color:#24292E;">      </span><span style="color:#005CC5;">&quot;import&quot;</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&quot;./dist/bundle.esm.mjs&quot;</span><span style="color:#24292E;">,</span></span>
<span class="line"><span style="color:#24292E;">      </span><span style="color:#005CC5;">&quot;require&quot;</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&quot;./dist/bundle.umd.js&quot;</span></span>
<span class="line"><span style="color:#24292E;">    },</span></span>
<span class="line"><span style="color:#24292E;">    </span><span style="color:#005CC5;">&quot;./dist/css/*&quot;</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&quot;./dist/css/*&quot;</span><span style="color:#24292E;">,</span></span>
<span class="line"><span style="color:#24292E;">    </span><span style="color:#005CC5;">&quot;./package.json&quot;</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&quot;./package.json&quot;</span></span>
<span class="line"><span style="color:#24292E;">  }</span></span>
<span class="line"><span style="color:#24292E;">}</span></span></code></pre></div><p><code>import</code> and <code>require</code> now resolve to the right build automatically. The ESM file is <code>.mjs</code> so Node loads it as ESM without the package needing <code>&quot;type&quot;: &quot;module&quot;</code>.</p><div class="warning custom-block"><p class="custom-block-title">Deep imports are no longer reachable</p><p>An <code>exports</code> map is a boundary. If you were reaching into the package — <code>import … from &quot;copper3d/dist/bundle.esm.js&quot;</code> — it will stop resolving. Import from the package root, or from <code>copper3d/dist/css/...</code> for the stylesheet.</p></div><h3 id="moduleresolution-in-your-tsconfig" tabindex="-1"><code>moduleResolution</code> in your tsconfig <a class="header-anchor" href="#moduleresolution-in-your-tsconfig" aria-label="Permalink to &quot;\`moduleResolution\` in your tsconfig&quot;">​</a></h3><p>copper3d imports three&#39;s addons as <code>three/addons/*</code>, which three exposes <strong>only</strong> through its <code>exports</code> map. TypeScript&#39;s legacy <code>&quot;node&quot;</code> resolution predates exports maps and cannot follow those paths, so if your <code>tsconfig.json</code> says:</p><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#E1E4E8;">{ </span><span style="color:#79B8FF;">&quot;compilerOptions&quot;</span><span style="color:#E1E4E8;">: { </span><span style="color:#79B8FF;">&quot;moduleResolution&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;node&quot;</span><span style="color:#E1E4E8;"> } }</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292E;">{ </span><span style="color:#005CC5;">&quot;compilerOptions&quot;</span><span style="color:#24292E;">: { </span><span style="color:#005CC5;">&quot;moduleResolution&quot;</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&quot;node&quot;</span><span style="color:#24292E;"> } }</span></span></code></pre></div><p>move it to <code>&quot;bundler&quot;</code> (Vite, webpack, Rollup) or <code>&quot;node16&quot;</code> / <code>&quot;nodenext&quot;</code> (Node). Leaving it on <code>&quot;node&quot;</code> also means TypeScript ignores copper3d&#39;s own <code>exports</code> map and may not find its types at all.</p><h3 id="the-revision-check" tabindex="-1">The revision check <a class="header-anchor" href="#the-revision-check" aria-label="Permalink to &quot;The revision check&quot;">​</a></h3><p>At import, copper3d compares the three revision it was <strong>built</strong> against with the one actually <strong>loaded</strong>, and logs a <code>console.error</code> on a mismatch:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">copper3d was built against three r186, but three r180 is loaded.</span></span>
<span class="line"><span style="color:#e1e4e8;">Install the three version copper3d&#39;s peerDependencies name.</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">copper3d was built against three r186, but three r180 is loaded.</span></span>
<span class="line"><span style="color:#24292e;">Install the three version copper3d&#39;s peerDependencies name.</span></span></code></pre></div><p>npm refuses an incompatible peer at install time, but yarn 1 and pnpm only warn — and three changes behaviour between minor releases, so a mismatch is worth seeing somewhere it cannot be scrolled past. The check never throws; it reports and carries on.</p><p>A build from source with nothing injected skips the comparison.</p><h2 id="what-did-not-change" tabindex="-1">What did <em>not</em> change <a class="header-anchor" href="#what-did-not-change" aria-label="Permalink to &quot;What did *not* change&quot;">​</a></h2><ul><li>Every copper3d class, method, option and type. No call sites need editing.</li><li><code>copperRenderer</code>, <code>copperScene</code>, <code>NrrdTools</code>, the loaders, the segmentation engine.</li><li>The UMD build is still at <code>dist/bundle.umd.js</code>, now with <code>three</code> mapped to the <code>THREE</code> global.</li></ul><div class="tip custom-block"><p class="custom-block-title">The UMD build is for <code>require</code>, not a <code>&lt;script&gt;</code> tag</p><p>Only three&#39;s <strong>core</strong> has a browser global. <code>three/addons/*</code> has none, so a bare script tag cannot satisfy copper3d&#39;s addon imports. Use a bundler, or the ESM build.</p></div><h2 id="checklist" tabindex="-1">Checklist <a class="header-anchor" href="#checklist" aria-label="Permalink to &quot;Checklist&quot;">​</a></h2><ol><li><code>npm install copper3d three@~0.186.0</code> (and <code>-D @types/three@~0.186.0</code> for TypeScript).</li><li>If your <code>tsconfig.json</code> has <code>&quot;moduleResolution&quot;: &quot;node&quot;</code>, change it.</li><li>Replace any deep import of <code>copper3d/dist/...</code> with a root import.</li><li>Load the app once and check the console for the revision-mismatch error.</li></ol><p>Nothing else. If step 4 is quiet and the app builds, you are done.</p>`,29);function u(y,g,E,m,q,b){const o=t("Badge");return n(),p("div",null,[s("h1",d,[e("Upgrading to 4.0 "),l(o,{type:"warning",text:"breaking"}),e(),i]),h])}const F=a(r,[["render",u]]);export{v as __pageData,F as default};
